"use client";
import { useRef, useState } from "react";
import { useTypeLoop, type TypographyMotionProps } from "./typography-shared";
import { typeGraphemes } from "./typography-math";
export interface TypewriterProps extends Omit<TypographyMotionProps, "trigger" | "progress"> {
  phrases?: string[];
  typeSpeed?: number;
  deleteSpeed?: number;
  pauseTyped?: number;
  pauseDeleted?: number;
  loop?: boolean;
  cursor?: string;
  onPhraseChange?: (phrase: string, index: number) => void;
}
export function Typewriter({
  text,
  phrases,
  typeSpeed = 70,
  deleteSpeed = 35,
  pauseTyped = 1400,
  pauseDeleted = 300,
  loop = true,
  cursor = "|",
  className,
  style,
  replayKey,
  onComplete,
  onPhraseChange,
}: TypewriterProps) {
  const values = phrases?.length
    ? phrases
    : text !== undefined
      ? [text]
      : ["Built for runners.", "Designed for every mile.", "Made to perform."];
  const signature = JSON.stringify(values);
  const root = useRef<HTMLSpanElement>(null),
    state = useRef({ index: 0, count: 0, phase: "type", next: 0, signature: "", done: false });
  const [visible, setVisible] = useState(values[0] ?? "");
  const [current, setCurrent] = useState(0);
  useTypeLoop(
    root,
    (time, _delta, reduced) => {
      if (reduced) {
        setVisible(values[0] ?? "");
        setCurrent(0);
        return;
      }
      const s = state.current;
      if (s.signature !== `${signature}:${replayKey}:${loop}`) {
        setCurrent(0);
        Object.assign(s, {
          index: 0,
          count: 0,
          phase: "type",
          next: 0,
          signature: `${signature}:${replayKey}:${loop}`,
          done: false,
        });
      }
      if (s.done) return false;
      if (time < s.next) return;
      const phrase = values[s.index] ?? "",
        chars = typeGraphemes(phrase);
      if (s.phase === "type") {
        s.count++;
        s.next = time + Math.max(10, typeSpeed);
        if (s.count >= chars.length) {
          s.count = chars.length;
          s.phase = "hold";
          s.next = time + Math.max(0, pauseTyped);
          onPhraseChange?.(phrase, s.index);
        }
      } else if (s.phase === "hold") {
        if (!loop && s.index === values.length - 1) {
          s.done = true;
          onComplete?.();
          return false;
        }
        s.phase = "delete";
        s.next = time;
      } else if (s.phase === "delete") {
        s.count--;
        s.next = time + Math.max(10, deleteSpeed);
        if (s.count <= 0) {
          s.count = 0;
          s.phase = "empty";
          s.next = time + Math.max(0, pauseDeleted);
        }
      } else {
        s.index = (s.index + 1) % values.length;
        s.phase = "type";
        s.next = time;
        setCurrent(s.index);
      }
      setVisible(
        typeGraphemes(values[s.index] ?? "")
          .slice(0, s.count)
          .join(""),
      );
    },
    `${signature}:${replayKey}:${loop}`,
  );
  return (
    <span
      ref={root}
      className={className}
      style={{ display: "inline-grid", ...style }}
      data-typography="typewriter"
      aria-label={values[current] ?? values[0] ?? ""}
    >
      <span aria-hidden="true" style={{ gridArea: "1/1", visibility: "hidden" }}>
        {values.reduce((a, b) => (a.length > b.length ? a : b), "")}
        {cursor}
      </span>
      <span aria-hidden="true" style={{ gridArea: "1/1" }}>
        <span data-type-typed="">{visible}</span>
        <span data-type-cursor="" style={{ fontWeight: 300, marginLeft: ".03em" }}>
          {cursor}
        </span>
      </span>
    </span>
  );
}
